import React from "react";
import Slider from "react-slick";


const banners = [
  "react-login-app/images/banner1.jpg",
  "/images/banner2.jpg",
  "/images/banner3.jpg"
];

const BannerCarousel = () => {
  const settings = {
    dots: true,
    infinite: true,
    speed: 600,
    slidesToShow: 1,
    slidesToScroll: 1,
    autoplay: true,
    autoplaySpeed: 4000, // 4 seconds
    arrows: false,
  };

  return (
    <div className="banner-carousel">
      <Slider {...settings}>
        {banners.map((img, idx) => (
          <img key={idx} src={img} alt={`Banner ${idx}`} className="banner-img" />
        ))}
      </Slider>
    </div>
  );
};

export default BannerCarousel;
